,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT o.order_id,',
'    o.order_datetime,',
'    o.customer_id,',
'    o.order_status,',
'    o.store_id,',
'    (SELECT Sum(unit_price * quantity)',
'        FROM   order_items i',
'        WHERE  i.order_id = o.order_id) total',
'FROM   orders o',
'WHERE  order_id = :P17_ORDER'))
,p_lazy_loading=>false
